"""The catalog of model providers the hub ships (``model_catalog.json``, generated by
``scripts/generate_model_catalog.py`` from a tag of OmniRoute, MIT, github.com/cheaper-inference/OmniRoute).

Every provider a member may add an account for: the chat LLMs OmniRoute reaches by a base URL and an API key (groups
apikey, free, aggregator, inference, regional, local), then Custom OpenAI-compatible and Custom Anthropic-compatible,
and the Claude subscription, which signs in by setup-token or OAuth and never goes through the gateway (``via`` is
``login``; every other entry is ``gateway``). An entry has ``id``, ``alias`` (the prefix the gateway reads in a model
name), ``name``, ``group``, ``color``, ``text_icon``, ``website``, ``key_hint``, ``base_url`` (the root of the API,
not the /chat/completions path), ``api_format`` (openai, anthropic, openai-responses or gemini), ``default_model``,
``key_required`` and ``free``. ``source`` names the OmniRoute version, commit and licence the file came from.

``GATEWAY_VERSION`` is the version of the OmniRoute image the gateway runs, so that alias and model names match what
the gateway serves; a test fails when it differs from the catalog's. A pure module: the server and the CLI read it.
"""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path

GATEWAY_VERSION = "3.8.52"
PATH = Path(__file__).with_name("model_catalog.json")


@lru_cache(maxsize=1)
def load() -> dict:
    """The whole file: ``source``, ``groups`` and ``providers``."""
    return json.loads(PATH.read_text(encoding="utf-8"))


def providers() -> list[dict]:
    return load()["providers"]


def find(provider_id: str) -> dict | None:
    """The entry of the provider with this id, or None."""
    return next((entry for entry in providers() if entry["id"] == provider_id), None)
